import 'package:nhost_dart/nhost_dart.dart';

void main() async {
  final nhost = NhostClient(
    subdomain: Subdomain(
      region: 'eu-central-1',
      subdomain: 'backend-5e69d1d7',
    ),
  );

  final authResponse = await nhost.auth.signUp(
    email: 'new-user@gmail.com',
    password: 'password-1',
  );

  await nhost.auth.signOut();
  nhost.close();
}
